--
-- Table structure for table `land_lord_reports`
--

CREATE TABLE `land_lord_reports` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `landload_id` bigint(20) UNSIGNED DEFAULT NULL,
  `land_lord_name` text DEFAULT NULL,
  `land_lord_email` text DEFAULT NULL,
  `land_lord_phone` text DEFAULT NULL,
  `land_lord_address` text DEFAULT NULL,
  `start_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `regenerate_report` text DEFAULT NULL,
  `total_income` bigint(20) DEFAULT NULL,
  `total_expense` bigint(20) DEFAULT NULL,
  `total_payment` bigint(20) DEFAULT NULL,
  `target_year` varchar(255) DEFAULT NULL,
  `target_type` varchar(255) DEFAULT NULL,
  `target_month` varchar(255) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

