--
-- Table structure for table `rooms`
--

CREATE TABLE `rooms` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `landload_id` bigint(20) UNSIGNED DEFAULT NULL,
  `region_id` bigint(20) UNSIGNED DEFAULT NULL,
  `area_id` bigint(20) UNSIGNED DEFAULT NULL,
  `name` text DEFAULT NULL,
  `status` varchar(255) DEFAULT NULL,
  `is_active` varchar(255) DEFAULT NULL,
  `number_of_rooms` int(11) DEFAULT NULL,
  `room_size` text DEFAULT NULL,
  `bed_rooms` int(11) DEFAULT NULL,
  `sitting_rooms` int(11) DEFAULT NULL,
  `dining_rooms` int(11) DEFAULT NULL,
  `indoor_toilets` int(11) DEFAULT NULL,
  `price` int(11) DEFAULT NULL,
  `landload_price` int(11) DEFAULT NULL,
  `image` text DEFAULT NULL,
  `images` text DEFAULT NULL,
  `furnishings` text DEFAULT NULL,
  `utilities` text DEFAULT NULL,
  `internet_access` text DEFAULT NULL,
  `security` text DEFAULT NULL,
  `amenities` text DEFAULT NULL,
  `remarks` text DEFAULT NULL,
  `house_id` int(11) DEFAULT NULL,
  `commission_type` tinyint(4) DEFAULT NULL,
  `flate_rate_amount` int(11) DEFAULT NULL,
  `percentage_rate` decimal(10,0) DEFAULT NULL,
  `state` varchar(100) DEFAULT 'Ready',
  `floor` text DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

